sys_script_include.script:
var UpcomingEventsUtils = Class.create();
UpcomingEventsUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUpcomingEvents: function() {
        gs.info('--- getUpcomingEvents called ---');
        var events = [];
        var gr = new GlideRecord('x_1790227_event_ma_event');
        gr.query();

        while (gr.next()) {
            events.push({
                sys_id: gr.getUniqueValue(),
                name: gr.getValue('u_event_name'),
                date: gr.getDisplayValue('u_event_date'),
                location: gr.getValue('u_location'),
                status: gr.getValue('u_status')
            });
        }

        gs.info('Events Fetched Count: ' + events.length);

        return JSON.stringify(events);
    },

    type: 'UpcomingEventsUtils'
});
